using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Windows.Forms;
using Microsoft.Win32;
using Microsoft.Web.WebView2.Core;

class FontAxisInfo { public string tag,name;public double min,max,normal; }
class FontInstanceInfo { public string name;public Dictionary<string,double> coordinates=new Dictionary<string,double>(); }
class FontRecord {public string id,family,style;public int weight;public bool italic;public List<FontAxisInfo> axes=new List<FontAxisInfo>();public List<FontInstanceInfo> instances=new List<FontInstanceInfo>();[System.Web.Script.Serialization.ScriptIgnore]public string path;[System.Web.Script.Serialization.ScriptIgnore]public int offset;}
static partial class OpenTypeReader {
 static int U16(byte[] b,int p){return (b[p]<<8)|b[p+1];}static int I32(byte[] b,int p){return (b[p]<<24)|(b[p+1]<<16)|(b[p+2]<<8)|b[p+3];}static double Fixed(byte[] b,int p){return I32(b,p)/65536.0;}static string Tag(byte[] b,int p){return Encoding.ASCII.GetString(b,p,4);}
 static void W16(byte[] b,int p,int v){b[p]=(byte)(v>>8);b[p+1]=(byte)v;}static void W32(byte[] b,int p,uint v){b[p]=(byte)(v>>24);b[p+1]=(byte)(v>>16);b[p+2]=(byte)(v>>8);b[p+3]=(byte)v;}
 static Dictionary<string,int[]> Tables(byte[] bytes,int offset){var result=new Dictionary<string,int[]>();int count=U16(bytes,offset+4);if(count<1||count>400)throw new Exception("Tabla de fuentes inválida");for(int i=0;i<count;i++){int p=offset+12+i*16,start=I32(bytes,p+8),length=I32(bytes,p+12);if(start<0||length<0||(long)start+length>bytes.Length)throw new Exception("Fuente incompleta");result[Tag(bytes,p)]=new[]{start,length,p};}return result;}
 static string Name(byte[] b,int table,int id){int count=U16(b,table+2),strings=table+U16(b,table+4),best=-1;string chosen="";for(int i=0;i<count;i++){int p=table+6+i*12;if(U16(b,p+6)!=id)continue;int platform=U16(b,p),language=U16(b,p+4),len=U16(b,p+8),start=strings+U16(b,p+10),score=(platform==3?100:platform==0?80:0)+(language==0x409?10:0);if(start<0||start+len>b.Length||score<=best)continue;try{chosen=(platform==0||platform==3?Encoding.BigEndianUnicode:Encoding.GetEncoding(1252)).GetString(b,start,len).Trim('\0',' ');best=score;}catch{}}return chosen;}
 public static List<FontRecord> Read(string path){byte[] b=File.ReadAllBytes(path);if(b.Length<12||b.Length>80000000)return new List<FontRecord>();int[] offsets=Tag(b,0)=="ttcf"?Enumerable.Range(0,Math.Min(I32(b,8),100)).Select(i=>I32(b,12+i*4)).ToArray():new[]{0};var result=new List<FontRecord>();foreach(int offset in offsets)try{var t=Tables(b,offset);if(!t.ContainsKey("name"))continue;int names=t["name"][0];string family=Name(b,names,16);if(family.Length==0)family=Name(b,names,1);string style=Name(b,names,17);if(style.Length==0)style=Name(b,names,2);if(string.IsNullOrWhiteSpace(family))continue;string id;using(var sha=SHA256.Create())id=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(path.ToLowerInvariant()+"#"+offset+"#"+File.GetLastWriteTimeUtc(path).Ticks))).Replace("-","").Substring(0,24);var record=new FontRecord{path=path,offset=offset,id=id,family=family,style=style.Length>0?style:"Regular",weight=400};if(t.ContainsKey("OS/2")){int os=t["OS/2"][0];record.weight=Math.Max(1,Math.Min(1000,U16(b,os+4)));if(t["OS/2"][1]>=64)record.italic=(U16(b,os+62)&1)!=0;}else if(t.ContainsKey("head")){record.italic=(U16(b,t["head"][0]+44)&2)!=0;}
 if(t.ContainsKey("fvar")){int f=t["fvar"][0],axisStart=f+U16(b,f+4),axes=U16(b,f+8),axisSize=U16(b,f+10),instances=U16(b,f+12),instanceSize=U16(b,f+14);if(axes>32||axisSize<20||instances>500)throw new Exception("Ejes inválidos");for(int i=0;i<axes;i++){int p=axisStart+i*axisSize;record.axes.Add(new FontAxisInfo{tag=Tag(b,p),name=Name(b,names,U16(b,p+18)),min=Fixed(b,p+4),normal=Fixed(b,p+8),max=Fixed(b,p+12)});}int start=axisStart+axes*axisSize;for(int i=0;i<instances;i++){int p=start+i*instanceSize;var inst=new FontInstanceInfo{name=Name(b,names,U16(b,p))};for(int a=0;a<axes;a++)inst.coordinates[record.axes[a].tag]=Fixed(b,p+4+a*4);record.instances.Add(inst);}}
 result.Add(record);}catch{}return result;}
 // TTC collections contain offsets into the collection; rebuild a standalone face for Chromium.
 public static byte[] Face(FontRecord record){byte[] b=File.ReadAllBytes(record.path);if(Tag(b,0)!="ttcf")return b;var tables=Tables(b,record.offset).OrderBy(k=>k.Key,StringComparer.Ordinal).ToArray();int count=tables.Length,total=12+count*16;foreach(var item in tables)total+=(item.Value[1]+3)&~3;var output=new byte[total];Array.Copy(b,record.offset,output,0,4);W16(output,4,count);int power=1,selector=0;while(power*2<=count){power*=2;selector++;}W16(output,6,power*16);W16(output,8,selector);W16(output,10,count*16-power*16);int cursor=12+count*16,head=-1;for(int i=0;i<count;i++){var table=tables[i];int p=12+i*16;Array.Copy(Encoding.ASCII.GetBytes(table.Key),0,output,p,4);Array.Copy(b,table.Value[0],output,cursor,table.Value[1]);if(table.Key=="head"){head=cursor;W32(output,head+8,0);}uint sum=0;for(int k=0;k<((table.Value[1]+3)&~3);k+=4)unchecked{sum+=(uint)I32(output,cursor+k);}W32(output,p+4,sum);W32(output,p+8,(uint)cursor);W32(output,p+12,(uint)table.Value[1]);cursor+=(table.Value[1]+3)&~3;}uint checksum=0;for(int i=0;i<output.Length;i+=4)unchecked{checksum+=(uint)I32(output,i);}if(head>=0)unchecked{W32(output,head+8,0xB1B0AFBA-checksum);}return output;}
}
partial class Desktop {
 List<FontRecord> fontCatalog=new List<FontRecord>();List<string> fontFolders=new List<string>();object fontLock=new object();bool fontCatalogLoaded;
 string FontFoldersFile{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LibroStudio","font-folders.json");}}
 void InitializeFontResources(){try{if(File.Exists(FontFoldersFile))fontFolders=json.Deserialize<List<string>>(File.ReadAllText(FontFoldersFile))??new List<string>();}catch{}view.CoreWebView2.AddWebResourceRequestedFilter("https://fonts.maquetario.local/*",CoreWebView2WebResourceContext.Font);view.CoreWebView2.WebResourceRequested+=delegate(object sender,CoreWebView2WebResourceRequestedEventArgs e){if(!e.Request.Uri.StartsWith("https://fonts.maquetario.local/",StringComparison.Ordinal))return;try{string id=new Uri(e.Request.Uri).Segments.Last().Split('.')[0];FontRecord record;lock(fontLock)record=packageFaces.Concat(fontCatalog).FirstOrDefault(f=>f.id==id);if(record==null){e.Response=view.CoreWebView2.Environment.CreateWebResourceResponse(null,404,"Not found","");return;}byte[] bytes=OpenTypeReader.Face(record);e.Response=view.CoreWebView2.Environment.CreateWebResourceResponse(new MemoryStream(bytes),200,"OK","Content-Type: font/ttf\r\nAccess-Control-Allow-Origin: https://librostudio.local\r\nCache-Control: private, max-age=3600");}catch{e.Response=view.CoreWebView2.Environment.CreateWebResourceResponse(null,404,"Font unavailable","");}};}
 IEnumerable<string> WalkFontFolder(string folder,bool recursive){var result=new List<string>();if(!Directory.Exists(folder))return result;try{result.AddRange(Directory.GetFiles(folder).Where(p=>new[]{".ttf",".otf",".ttc"}.Contains(Path.GetExtension(p).ToLowerInvariant())));if(recursive)foreach(var dir in Directory.GetDirectories(folder)){try{if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)==0)result.AddRange(WalkFontFolder(dir,true));}catch{}}}catch{}return result;}
 object ScanFonts(){var windows=Environment.GetFolderPath(Environment.SpecialFolder.Fonts);var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var path in WalkFontFolder(windows,false))paths.Add(path);foreach(var path in WalkFontFolder(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Microsoft","Windows","Fonts"),false))paths.Add(path);foreach(var root in new[]{Registry.LocalMachine,Registry.CurrentUser})try{using(var key=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts")){if(key==null)continue;foreach(var name in key.GetValueNames()){string value=key.GetValue(name) as string;if(string.IsNullOrEmpty(value))continue;value=Environment.ExpandEnvironmentVariables(value);if(!Path.IsPathRooted(value))value=Path.Combine(windows,value);if(File.Exists(value))paths.Add(value);}}}catch{}foreach(var folder in fontFolders.ToArray())foreach(var path in WalkFontFolder(folder,true))paths.Add(path);var catalog=new List<FontRecord>();foreach(var path in paths)try{catalog.AddRange(OpenTypeReader.Read(path));}catch{}catalog=catalog.GroupBy(f=>f.family+"|"+f.style+"|"+f.weight+"|"+f.italic).Select(g=>g.First()).OrderBy(f=>f.family,StringComparer.CurrentCultureIgnoreCase).ThenBy(f=>f.weight).ToList();lock(fontLock){fontCatalog=catalog;fontCatalogLoaded=true;}return new{faces=catalog,folders=fontFolders.ToArray(),files=paths.Count,variableFaces=catalog.Count(f=>f.axes.Count>0)};}
 async Task LoadFontCatalog(string id,bool refresh){if(fontCatalogLoaded&&!refresh){lock(fontLock)Reply(id,new{faces=fontCatalog,folders=fontFolders.ToArray(),files=fontCatalog.Select(f=>f.path).Distinct().Count(),variableFaces=fontCatalog.Count(f=>f.axes.Count>0)});return;}var catalog=await Task.Run(()=>ScanFonts());Reply(id,catalog);}
 async Task ChooseFontFolder(string id){using(var d=new FolderBrowserDialog{Description=language=="en"?"Choose a folder containing TTF, OTF or TTC fonts":language=="pt"?"Escolha uma pasta com fontes TTF, OTF ou TTC":"Elegí una carpeta con fuentes TTF, OTF o TTC",ShowNewFolderButton=false}){if(d.ShowDialog(this)!=DialogResult.OK){Reply(id,null);return;}if(!fontFolders.Contains(d.SelectedPath,StringComparer.OrdinalIgnoreCase))fontFolders.Add(d.SelectedPath);Directory.CreateDirectory(Path.GetDirectoryName(FontFoldersFile));File.WriteAllText(FontFoldersFile,json.Serialize(fontFolders));}await LoadFontCatalog(id,true);}
}
